BRUCE='<a href="https://brucemrushing.com/">Bruce Rushing</a>'
P=[]
def pub(sec,id,year,typ,title,venue,links=(),abstract=None):
    P.append(dict(sec=sec,id=id,year=year,typ=typ,title=title,venue=venue,links=links,abstract=abstract))
pub('book','pub-book','Forthcoming','Book','Radical AI Interpretability',f'Cambridge University Press, with {BEN}',
 [('Draft','https://philpapers.org/archive/HERRAI-5.pdf'),('arXiv','https://arxiv.org/abs/2606.26523')],
 "We develop a framework for interpreting AI systems as agents, drawing on the philosophical tradition of radical interpretation and the tools of mechanistic interpretability. The core question is: given the computational facts about a system, how do we solve for its beliefs, desires, and meanings? This matters increasingly for safety. We want to be able to trust the systems we deploy, whether by understanding their goals or, more modestly, by reliably detecting deception. Interpretability researchers are building tools to read beliefs and desires off a model’s internals, but there is no settled account of when such a tool has succeeded. This book supplies one. We propose criteria on both representationalist and interpretationist approaches, and tie each to tests current interpretability methods can carry out. A central lesson is that these attributions cannot be made piecemeal. Beliefs, desires, and the propositional structure they presuppose are jointly constrained, and a method that fixes one while measuring the others inherits whatever distortions that introduces. This holism becomes pressing for AI systems, which may not share the interpreter’s concepts. However, it also provides leverage: a system’s attitudes constrain its propositional structure, that structure constrains which attitudes can be attributed, and mechanistic interpretability can help us measure both.")
pub('articles','pub-social-sciences','2026','Article','Why Are the Social Sciences Hard? Two New Hypotheses',
 f'<a href="https://www.sciencedirect.com/science/article/pii/S003936812600083X"><i>Studies in History and Philosophy of Science</i></a>, with {AYDIN} and <a href="https://uni-tuebingen.de/en/faculties/faculty-of-economics-and-social-sciences/subjects/department-of-social-sciences/education-sciences-and-psychology/institute/staff/orona-gabe-dr/">Gabe Avakian Orona</a>',
 [('Blog version','https://www.lesswrong.com/posts/3dkKgHEnkjAXuc3jQ/why-are-the-human-sciences-hard-two-new-hypotheses')],
 "Debates about whether the social sciences are <em>harder</em> than the natural sciences rarely analyze what discipline-level hardness amounts to. We offer a simple formal framework that models disciplines as sets of prediction tasks with associated difficulty, and links judgments of hardness to a discipline’s best-achieved performance on such tasks and to the psychological <em>impressiveness</em> of those successes. Within this framework we develop two hypotheses about why the social sciences appear hard. The <em>rigid demands</em> hypothesis holds that, in the social sciences, we are precommitted to a narrow class of prediction tasks, which restricts the usual strategy of changing the question to a more tractable one and thereby lowers expected best performance. The <em>fruit in the hand</em> hypothesis holds that, due to evolutionary and cultural pressures, humans already solve many low-difficulty prediction tasks about human behaviour, so these do not register as scientific successes and harder residual tasks dominate our impressions. We show that, even if task-level difficulty distributions were identical across domains, these mechanisms would make the social sciences appear harder than the natural sciences. This undermines straightforward inferences from differences in headline successes to claims about the intrinsic difficulty of the social domain. This framework opens new lines of inquiry regarding perceptions of the difficulty of the sciences.")
pub('articles','pub-natural-salience','2026','Article','Naturalizing Natural Salience',
 f'<a href="https://www.journals.uchicago.edu/doi/10.1086/725654"><i>British Journal for the Philosophy of Science</i></a>, with {JACK}',[('Free version','https://philsci-archive.pitt.edu/22098/')],
 "Grice, Lewis, and Skyrms proposed similar distinctions between kinds of meaning. The meaning of terms in human language, as Lewis and Skyrms had it, is “conventional.” Skyrms presented models showing how it is possible for conventional meaning to evolve in a population without reliance on pre-existing meaning. But one might think of conventionality as coming in degrees, based on whether the evolutionary process begins with “natural saliences.” We propose a theory of natural salience and several extensions of Skyrms’s models to capture this notion. These models reveal that natural saliences can hinder, as well as help, the evolution of language.")
pub('articles','pub-misalignment','2026','Proceedings','A Decision-Theoretic Approach for Managing Misalignment',
 f'<a href="https://ojs.aaai.org/index.php/IASEAI/article/view/43026"><i>Proceedings of the Second Conference of the International Association for Safe and Ethical Artificial Intelligence</i></a>, with <a href="https://www.linkedin.com/in/abinav-chari1">Abinav Chari</a>, <a href="https://www.linkedin.com/in/isabelle-athena-qian">Isabelle Qian</a>, <a href="https://www.sreesharvesh.com/">Sree Sharvesh</a>, and {BEN}',
 [('arXiv','https://arxiv.org/abs/2512.15584')],
 "When should we delegate decisions to AI systems? While the value alignment literature has developed techniques for shaping AI values, less attention has been paid to how to determine, under uncertainty, when imperfect alignment is good enough to justify delegation. We argue that rational delegation requires balancing an agent’s value (mis)alignment with its epistemic accuracy and its reach (the acts it has available). This paper introduces a formal, decision-theoretic framework to analyze this tradeoff precisely accounting for a principal’s uncertainty about these factors. Our analysis reveals a sharp distinction between two delegation scenarios. First, universal delegation (trusting an agent with any problem) demands near-perfect value alignment and total epistemic trust, conditions rarely met in practice. Second, we show that context-specific delegation can be optimal even with significant misalignment. An agent’s superior accuracy or expanded reach may grant access to better overall decision problems, making delegation rational in expectation. We develop a novel scoring framework to quantify this ex ante decision. Ultimately, our work provides a principled method for determining when an AI is aligned enough for a given context, shifting the focus from achieving perfect alignment to managing the risks and rewards of delegation under uncertainty.")
pub('articles','pub-deference','2025','Article','Deference and Decision',
 '<a href="https://link.springer.com/article/10.1007/s11238-025-10036-0"><i>Theory and Decision</i></a>, with <a href="https://gerardrothfus.com/">Gerard Rothfus</a>',
 [('Free link','https://rdcu.be/ekuAY')],
 "Consider two principles of rational decision making. One says that you should never use the value of events that are inconsistent with your evidence to assess what to do. The other says that, if you know what a more informed version of yourself would do, then you should already do likewise with your current information. We show that no decision theory which agrees with evidential decision theory (EDT) and causal decision theory (CDT) whenever they agree can satisfy both principles. In particular, assuming that agents update via Bayesian conditioning, EDT satisfies the former and violates the latter, while CDT violates the former and satisfies the latter. We show that the causalist can satisfy the first (at the cost of then violating the second) if she either uses a learning rule that changes her beliefs about counterfactuals in a particular way or uses a decision rule more in line with a rule proposed by Hitchcock (2016). We then employ these results to illuminate a core tension at the heart of the debate between evidentialists and causalists.")
pub('articles','pub-lie-detector','2025','Article','Still No Lie Detector for Language Models: Probing Empirical and Conceptual Roadblocks',
 f'<a href="https://doi.org/10.1007/s11098-023-02094-3"><i>Philosophical Studies</i></a>, with {BEN}',
 [('Free link','https://link.springer.com/epdf/10.1007/s11098-023-02094-3?sharing_token=SQMI6yIG-Y3_64NhDmPODPe4RwlQNchNByi7wbcMAY4V8cw3OTXTDNDj1o4J90P-1orE5NH7T79Dpp9kZfaa9-j_1GbmsAUVUqokbkR7Q9PTKBra4xq8wm8FZKqZl3dix_ZotmX5xKFy1OlLO3EqktXy-y4pCHPcdIh2Z6wU9Yk%3D')],
 "We consider the questions of whether or not large language models (LLMs) have beliefs, and, if they do, how we might measure them. First, we consider whether or not we should expect LLMs to have something like beliefs in the first place. We consider some recent arguments aiming to show that LLMs cannot have beliefs. We show that these arguments are misguided. We provide a more productive framing of questions surrounding the status of beliefs in LLMs, and highlight the empirical nature of the problem. With this lesson in hand, we evaluate two existing approaches for measuring the beliefs of LLMs, one due to Azaria and Mitchell (2023) and the other to Burns et al. (2022). Moving from the armchair to the desk chair, we provide empirical results that show that these methods fail to generalize in very basic ways. We then argue that, even if LLMs have beliefs, these methods are unlikely to be successful for conceptual reasons. Thus, there is still no lie-detector for LLMs. We conclude by suggesting some concrete paths for future work.")
pub('articles','pub-sifting','2025','Article','Sifting the Signal from the Noise',
 f'<a href="https://doi.org/10.1086/720805"><i>British Journal for the Philosophy of Science</i></a>, with {JACK}',[('Free version','https://philsci-archive.pitt.edu/20617/')],
 "Signaling games are useful for understanding how language emerges. In the standard models the dynamics in some sense already knows what the signals are, even if they do not yet have meaning. In this paper we relax this assumption, and develop a simple model we call an attention game in which agents have to learn which feature in their environment is the signal. We demonstrate that simple reinforcement learning agents can still learn to coordinate in contexts in which (i) the agents do not already know what the signal is and (ii) the other features in the agents’ environment are uncorrelated with the signal. Furthermore, we show that, in the cases in which other features are correlated with the signal, there is a surprising trade-off between learning what the signal is, and success in action. We show that the mutual information between a signal and a feature plays a key role in governing the accuracy and attention of the agent.")
pub('articles','pub-correlated-conventions','2025','Article','Invention and Evolution of Correlated Conventions',
 '<a href="https://www.journals.uchicago.edu/doi/10.1086/717161"><i>British Journal for the Philosophy of Science</i></a>, with <a href="https://faculty.sites.uci.edu/skyrms/">Brian Skyrms</a>',(),
 "An important feature of many conventions is that the agents use an asymmetry to coordinate their behaviour. We call these correlated conventions. However, a puzzle arises: since any asymmetry works as well as any other, what are the relevant asymmetries on which a given population founds its correlated conventions? In order to gain traction on this question we need an account of both the invention and evolution of correlated conventions. Invention has remained largely unexplored in the literature. In this paper we provide a simple model of the origin and subsequent dynamics of correlated conventions. This model can serve as a base for future investigation in this direction.")
pub('articles','pub-belief-standards','2025','Article','Standards for Belief Representations in LLMs',
 f'<a href="https://link.springer.com/article/10.1007/s11023-024-09709-6"><i>Minds and Machines</i></a>, with {BEN}',[('arXiv','https://arxiv.org/abs/2405.21030')],
 "As large language models (LLMs) continue to demonstrate remarkable abilities across various domains, computer scientists are developing methods to understand their cognitive processes, particularly concerning how (and if) LLMs internally represent their beliefs about the world. However, this field currently lacks a unified theoretical foundation to underpin the study of belief in LLMs. This article begins filling this gap by proposing adequacy conditions for a representation in an LLM to count as belief-like. We argue that, while the project of belief measurement in LLMs shares striking features with belief measurement as carried out in decision theory and formal epistemology, it also differs in ways that should change how we measure belief. Thus, drawing from insights in philosophy and contemporary practices of machine learning, we establish four criteria that balance theoretical considerations with practical constraints. Our proposed criteria include accuracy, coherence, uniformity, and use, which together help lay the groundwork for a comprehensive understanding of belief representation in LLMs. We draw on empirical work showing the limitations of using various criteria in isolation to identify belief representations.")
pub('articles','pub-pwea','2022','Article','Prediction with Expert Advice Applied to the Problem of Prediction with Expert Advice',
 '<a href="https://link.springer.com/article/10.1007/s11229-022-03809-5"><i>Synthese</i></a>',(),
 "We often need to have beliefs about things on which we are not experts. Luckily, we often have access to expert judgements on such topics. But how should we form our beliefs on the basis of expert opinion when experts conflict in their judgments? This is the core of the novice/2-expert problem in social epistemology. A closely related question is important in the context of policy making: how should a policy maker use expert judgments when making policy in domains in which she is not herself an expert? This question is more complex, given the messy and strategic nature of politics. In this paper we argue that the prediction with expert advice (PWEA) framework from machine learning provides helpful tools for addressing these problems. We outline conditions under which we should expect PWEA to be helpful and those under which we should not expect these methods to perform well.")
pub('articles','pub-pac','2020','Article','PAC Learning and Occam’s Razor: Probably Approximately Incorrect',
 '<a href="https://doi.org/10.1086/709786"><i>Philosophy of Science</i></a>',(),
 "Computer scientists have provided a distinct justification of Occam’s Razor. Using the probably approximately correct framework, they provide a theorem which they claim demonstrates that we should favour simpler hypotheses. The argument relies on a philosophical interpretation of the theorem. I argue that although, when supplemented with additional unstated assumptions, the proof of the theorem is mathematically sound, the standard interpretation of the result in the literature is misguided and that a better reading does not, in fact, support Occam’s Razor at all. In support of this, I state and prove a very similar theorem which, if interpreted the same way, would justify the contradictory Anti-Occam’s Razor, the principle that we should favour more complex hypotheses.")
pub('reviews','pub-review-buckner','2025','Review','Review of Cameron J. Buckner’s <i>From Deep Learning to Rational Machines</i>',
 f'<a href="https://www.cambridge.org/core/journals/philosophy-of-science/article/review-of-cameron-j-buckners-from-deep-learning-to-rational-machines-what-the-history-of-philosophy-can-teach-us-about-the-future-of-artificial-intelligence-cameron-j-buckner-from-deep-learning-to-rational-machines-what-the-history-of-philosophy-can-teach-us-about-the-future-of-artificial-intelligence-oxford-university-press/38939A09CEDA75735A96673256422EC9"><i>Philosophy of Science</i></a>, with {BRUCE}')
pub('reviews','pub-review-myrvold','2022','Review','Review of Wayne C. Myrvold’s <i>Beyond Chance and Credence</i>',
 '<a href="https://academic.oup.com/philmat/article-abstract/30/2/273/6554573"><i>Philosophia Mathematica</i></a>, with <a href="https://www.davidpeterwallisfreeborn.com/">David Peter Wallis Freeborn</a>',
 [('Free link','https://academic.oup.com/philmat/advance-article/doi/10.1093/philmat/nkac006/6554573?guestAccessKey=be69ceb8-26ba-47c8-a05b-1be9d51e9637')])
pub('review','pub-subnat','','Under review','Subjective Naturalism and Act Probabilities','Available on request.',(),
 "Can an agent assign probabilities to her own acts while she deliberates? This question splits decision theorists into two broad camps: those who believe deliberation crowds out prediction, and those who believe that deliberation welcomes prediction. I argue that philosophers are divided because they respond in different ways to a threat posed to agency for a certain kind of naturalized agent. I introduce two conditions that capture this kind of subjective naturalism: richness and austerity. I show that taking these two conditions poses a dilemma, and that both camps respond to the dilemma by violating one of these conditions. I provide a novel account of agency, called desirability tracking, which allows us to avoid the violations of richness that the crowding out camp commits, while also avoiding the violations of austerity that the welcoming camp commits. The account also allows us to extract the decision problems an agent takes herself to face from her own attitudes, as opposed to imposing them from the outside.")
pub('review','pub-causation','2026','Under review','A Bayesian Reduction of Causation',
 f'With {AYDIN}, {BEN}, and {BRUCE}',
 [('Preprint','https://aydinmohseni.com/wp-content/uploads/2026/03/A_Bayesian_Reduction_of_Causation.pdf')],
 "De Finetti conjectured that causation, like chance, reduces to patterns in subjective probability. Recent results on the Pearl Causal Hierarchy seem to foreclose this possibility, proving that causal claims are irreducible to probabilistic ones within structural causal models (SCMs). We show that the reduction succeeds after all. The apparent irreducibility arises from an implicit restriction on the agent’s representational resources: once the variable set is enriched to include naturalized intervention variables, interventional propositions reduce to ordinary probabilistic conditioning. To complete the subjectivist picture, we prove a de Finetti-style representation theorem establishing that an agent with exchangeable credences can be represented as simultaneously learning causal structure and the probabilities within that structure via standard Bayesian updating. We then show how this framework bears on the debate between evidential and causal decision theory, arguing that causal decision theory functions as a useful approximation of evidential reasoning over the full algebra. Within SCMs, causal reasoning reduces to subjective probability.")
pub('review','pub-grounding','','Under review','Grounding Human-Machine Decision-Making',
 'With <a href="https://sites.google.com/view/thomas-grote/startseite">Thomas Grote</a> and <a href="https://www.cvernade.com/">Claire Vernade</a>. Available on request.',(),
 "Machine learning systems now participate in many high-stakes decisions alongside human experts, yet the conceptual terrain remains fragmented. Inconsistent terminology and underspecified frameworks hinder study design and obscure when findings transfer across research contexts. We develop a unified decision-theoretic framework capturing four types of human-machine decision-making: human-in-the-loop (ML systems decide while humans monitor), decision-aid (humans decide with ML predictions), complementarity (division of labor by respective strengths), and collective decision-making (independent judgments combined by aggregation). Grounding these types in common formal apparatus reveals structural similarities often missed when studied in isolation, and predicts which failure modes can arise in each type. The framework connects the decision-aid literature to results from formal epistemology that characterize exactly when deference to a machine is rational, and it identifies two intervention points: modifying what information the machine communicates versus how humans respond. We extend these foundations to sequential settings where both parties learn over time, and discuss applications to attributing responsibility for erroneous decisions in human-machine systems.")
pub('review','pub-benign','','Under review','Benign Interpolation and Occam’s Razor',
 'With <a href="https://tomster.userweb.mwn.de/">Tom F. Sterkenburg</a> and <a href="https://romeijn.web.rug.nl/">Jan-Willem Romeijn</a>',
 [('arXiv','https://arxiv.org/abs/2608.03386')],
 "Contemporary deep learning methods generalize well even when they fit their training data perfectly, a phenomenon known as benign interpolation. This phenomenon cannot be accounted for by classical statistical learning theory and has prompted a range of attempted new explanations in the statistics and machine learning literature. A common feature of these new proposals is an appeal to a simplicity preference among interpolating models, often presented as a form of Occam’s razor. We clarify this debate for a philosophical audience and argue that this new appeal to simplicity creates an explanatory gap. The classical theory offers theorems which connect the simplicity of model classes to good generalization, thus underwriting methodological simplicity norms. The new accounts instead appeal to properties of individual models, which they interpret as a kind of simplicity. Lacking a provable connection to generalization, it is the name “simplicity” that does the work a theorem used to do, making a substantive and unargued assumption look like the application of a familiar methodological principle.")
pub('working','pub-cartesian','2021','Preprint','Cartesian Frames',
 'With <a href="http://scott.garrabrant.com/">Scott Garrabrant</a> and <a href="https://josiahlopezwild.com">Josiah Lopez-Wild</a>',
 [('arXiv','https://arxiv.org/abs/2109.10996')],
 "We introduce a novel framework, the theory of Cartesian frames (CF), that gives powerful tools for manipulating sets of acts. The CF framework takes as its most fundamental building block that an agent can freely choose from a set of available actions. The framework uses the mathematics of Chu spaces to develop a calculus of those sets of actions, how those actions change at various levels of description, and how different agents’ actions can combine when agents work in concert. We discuss how this framework might provide an illuminating perspective on issues in decision theory and formal epistemology.")
pub('working','pub-measure','','Manuscript','Measure for Measure: Problems with Probability in Decohering Worlds','Available on request.',(),
 "Quantum mechanics is one of our most successful physical theories. One prominent interpretation of quantum mechanics is the Everett interpretation, also called the “Many-Worlds Interpretation.” However, the Everett interpretation gives rise to a puzzle: probability seems to be absent from the theory. This is a problem, because the evidence we have for quantum mechanics is that its probabilistic predictions agree with the statistics of measurement outcomes. David Wallace has argued that we can use decision theory, via a representation theorem, to solve this probability puzzle. I argue that providing a representation theorem in which an agent is representable as maximizing a utility function with respect to what is mathematically a probability function is not sufficient to derive probability in the sense of credence, and thus that this solution to the problem fails.")

SECS=[('book','Book'),('articles','Articles'),('reviews','Book reviews'),('under-review','Under review'),('working-papers','Working papers')]
SECKEY={'review':'under-review','working':'working-papers'}
def item(p):
    # Under review is said by the section; a different status there (e.g. Revise and resubmit) still shows.
    typ=f'<span class="type">{p["typ"]}</span>' if (p['sec']=='working' or (p['sec']=='review' and p['typ']!='Under review')) else ''
    yr=f'<span class="year">{p["year"]}</span>' if p['year'] else ''
    meta=f'<div class="work-meta">{yr}{typ}</div>'
    links=''.join(f'<a href="{u.replace("&","&amp;") if "&amp;" not in u else u}">{l}</a>' for l,u in p['links'])
    ab=f'<details class="abs"><summary>Abstract</summary><p>{p["abstract"]}</p></details>' if p['abstract'] else ''
    if p['id'] in BIB: ab+=f'<details class="abs cite"><summary>Cite</summary><pre class="bib">{html.escape(BIB[p["id"]])}</pre><button type="button" class="copy-bib">Copy BibTeX</button></details>'
    linkrow=f'<div class="work-links">{links}{ab}</div>' if (links or ab) else ''
    return f'''      <li class="work" id="{p["id"]}">
        {meta}
        <div class="work-main">
          <p class="work-title">{p["title"]}</p>
          <p class="work-venue">{p["venue"]}</p>
          {linkrow}
        </div>
      </li>'''
out=[]
for key,label in SECS:
    items=[p for p in P if SECKEY.get(p['sec'],p['sec'])==key]
    out.append(f'''<section class="section" id="{key}" aria-labelledby="h-{key}">
  <p class="label" id="h-{key}">{label}</p>
  <div class="body">
    <ul class="works">
{chr(10).join(item(p) for p in items)}
    </ul>
  </div>
</section>
''')
counts={k:len([p for p in P if SECKEY.get(p['sec'],p['sec'])==k]) for k,_ in SECS}
sys.stdout.write(''.join(out))
sys.stderr.write(str(counts))
